class _FakeTokenStore implements TokenStore {
  final expirations = StreamController<void>.broadcast();
  String? accessToken = 'access-token';
  String? refreshToken = 'refresh-token';
  bool cleanupPending = false;

  @override
  Future<void> clear() async {
    accessToken = null;
    refreshToken = null;
  }

  @override
  Future<void> clearCleanupPending() async => cleanupPending = false;

  @override
  Future<void> expireSession() async {
    cleanupPending = true;
    await clear();
    cleanupPending = false;
    expirations.add(null);
  }

  @override
  Future<bool> isCleanupPending() async => cleanupPending;

  @override
  Future<void> markCleanupPending() async => cleanupPending = true;

  @override
  Future<String?> readAccessToken() async => accessToken;

  @override
  Future<String?> readRefreshToken() async => refreshToken;

  @override
  Stream<void> get sessionExpirations => expirations.stream;

  @override
  Future<void> writeTokens({
    required String accessToken,
    required String refreshToken,
  }) async {
    this.accessToken = accessToken;
    this.refreshToken = refreshToken;
  }
}

class _JsonAdapter implements HttpClientAdapter {
  RequestOptions? lastRequest;
  final failures = <String, Object>{};
  final requests = <RequestOptions>[];
  final responses = <String, ({int status, Object? body})>{};

  void fail(String path, Object error) {
    failures[path] = error;
  }

  void respond(String path, {required int status, required Object? body}) {
    responses[path] = (status: status, body: body);
  }

  @override
  Future<ResponseBody> fetch(
    RequestOptions options,
    Stream<Uint8List>? requestStream,
    Future<void>? cancelFuture,
  ) async {
    lastRequest = options;
    requests.add(options);
    final path = options.uri.path;
    final failure = failures[path];
    if (failure != null) throw failure;
    final (status, body) = switch (path) {
      '/api/v1/auth/login' || '/api/v1/auth/refresh' => (
        200,
        {
          'userId': 'synthetic-user',
          'accessToken': 'new-access',
          'refreshToken': 'new-refresh',
        },
      ),
      '/api/v1/auth/logout' => (204, const <String, dynamic>{}),
      '/api/v1/members/member-1/records' => (
        200,
        {
          'items': [
            {
              'id': 'record-1',
              'memberId': 'member-1',
              'type': 'Lab report',
              'title': 'Synthetic report',
              'recordedAt': '2026-08-04T00:00:00Z',
            },
          ],
        },
      ),
      '/api/v1/members/member-1/vitals' => (201, {'id': 'vital-1'}),
      '/api/v1/families/me' => (
        200,
        {
          'members': [
            {
              'id': 'member-1',
              'displayName': 'Synthetic Member',
              'relationshipLabel': 'Self',
            },
          ],
        },
      ),
      '/api/v1/members/member-1/triage-cases' => (
        200,
        [
          {
            'id': 'case-1',
            'status': 'APPROVED',
            'submittedAt': '2026-08-04T00:00:00Z',
          },
        ],
      ),
      '/api/v1/notifications/inbox' => (
        200,
        [
          {
            'id': 'notification-1',
            'createdAt': '2026-08-04T00:00:00Z',
            'isRead': false,
            'caseId': 'case-1',
            'caseStatus': 'APPROVED',
          },
        ],
      ),
      '/api/v1/notifications' => (
        200,
        [
          {
            'id': 'portal-notification-1',
            'createdAt': '2026-08-05T00:00:00Z',
            'type': 'APPOINTMENT_REQUESTED',
            'title': 'Appointment requested',
            'body': 'Synthetic appointment update.',
            'readAt': null,
          },
        ],
      ),
      '/api/v1/notifications/subscribe' => (204, const <String, dynamic>{}),
      '/api/v1/triage-cases/case-1/approved-guidance' => (
        200,
        {
          'caseId': 'case-1',
          'status': 'APPROVED',
          'finalAdvisory': 'Doctor-approved guidance.',
          'doctorName': 'Dr Test',
          'approvedAtLabel': 'Today',
        },
      ),
      '/api/v1/triage-cases/case-1/status' => (
        200,
        {
          'id': 'case-1',
          'status': 'FAILED_SAFE',
          'priority': 'ROUTINE',
          'failureCode': 'AGENT_UNAVAILABLE',
        },
      ),
      '/api/v1/members/member-1/familial-risk' => (
        200,
        {
          'caseId': 'case-1',
          'screeningGuidance':
              'Please discuss appropriate screening with a licensed clinician.',
          'disclaimer': 'Synthetic disclaimer',
        },
      ),
      '/api/v1/members/member-1/episodes' => (201, {'id': 'episode-1'}),
      '/api/v1/episodes/episode-1/triage' => (202, {'id': 'case-2'}),
      '/api/v1/unauthorized' => (401, {'title': 'Unauthorized'}),
      _ => (404, {'title': 'Not found'}),
    };
    final configured = responses[path];
    return ResponseBody.fromString(
      jsonEncode(configured == null ? body : configured.body),
      configured?.status ?? status,
      headers: {
        Headers.contentTypeHeader: [Headers.jsonContentType],
      },
    );
  }

  @override
  void close({bool force = false}) {}
}

void main() {
  late _FakeTokenStore tokenStore;
  late _JsonAdapter adapter;
  late ApiClient client;

  setUp(() {
    tokenStore = _FakeTokenStore();
    adapter = _JsonAdapter();
    final dio = Dio(BaseOptions(baseUrl: 'https://example.test/api/v1'))
      ..httpClientAdapter = adapter;
    client = ApiClient(tokenStore: tokenStore, dio: dio);
  });

  tearDown(() => tokenStore.expirations.close());

  test('auth API parses login and refresh tokens', () async {
    final api = DioAuthApi(client);
    final login = await api.login(
      email: 'synthetic@example.test',
      password: 'password',
    );
    final refresh = await api.refresh('refresh-token');

    expect(login.accessToken, 'new-access');
    expect(login.userId, 'synthetic-user');
    expect(refresh.refreshToken, 'new-refresh');
    expect(
      adapter.lastRequest?.headers['Authorization'],
      'Bearer access-token',
    );
  });

  test('auth API sends logout request', () async {
    await DioAuthApi(client).logout();

    expect(adapter.lastRequest?.uri.path, '/api/v1/auth/logout');
  });

  test('auth errors map to safe user-facing messages', () {
    DioException errorFor(int status) => DioException(
      requestOptions: RequestOptions(path: '/auth/login'),
      response: Response<void>(
        requestOptions: RequestOptions(path: '/auth/login'),
        statusCode: status,
      ),
    );

    expect(userFacingApiError(errorFor(401)), contains('incorrect'));
    expect(
      userFacingApiError(errorFor(403)),
      'Email or password is incorrect.',
    );
    expect(
      userFacingApiError(errorFor(500)),
      contains('temporarily unavailable'),
    );
    expect(userFacingApiError(Exception('synthetic')), contains('connection'));
  });

  test('record API scopes request to member and parses records', () async {
    final api = DioMobileApi(client);
    final records = await api.getRecords('member-1');

    expect(records.single.memberId, 'member-1');
    expect(adapter.lastRequest?.uri.path, '/api/v1/members/member-1/records');
    await api.addRecord(
      memberId: 'member-1',
      recordType: 'Note',
      title: 'Synthetic note',
      occurredOn: DateTime.utc(2026, 8, 4),
    );
    await api.addVital(
      memberId: 'member-1',
      vitalType: 'Synthetic vital',
      value: 1,
      unit: 'unit',
      measuredAt: DateTime.utc(2026, 8, 4),
    );
    expect(adapter.lastRequest?.uri.path, '/api/v1/members/member-1/vitals');
  });

  test('patient API parses patient-safe endpoints', () async {
    final api = DioPatientApi(
      client,
      devicePlatform: MobileDevicePlatform.android,
    );

    expect((await api.getMembers()).single.id, 'member-1');
    expect((await api.getCases('member-1')).single.id, 'case-1');
    expect(
      (await api.getCaseStatus('case-1'))['failureCode'],
      'AGENT_UNAVAILABLE',
    );
    final notifications = await api.getNotifications();
    expect(notifications.map((item) => item.id), [
      'portal-notification-1',
      'notification-1',
    ]);
    expect(notifications.first.isRead, isFalse);
    expect(notifications.last.caseStatus, 'APPROVED');
    expect(notifications.last.isRead, isTrue);
    final guidance = await api.getApprovedGuidance(
      caseId: 'case-1',
      memberId: 'member-1',
    );
    expect(guidance?.finalAdvisory, 'Doctor-approved guidance.');
    expect(adapter.lastRequest?.queryParameters['memberId'], 'member-1');
    expect(
      (await api.getApprovedFamilialRisk('member-1'))?.screeningGuidance,
      contains('licensed clinician'),
    );
    final caseId = await api.submitComplaint(
      memberId: 'member-1',
      chiefComplaint: 'Synthetic complaint',
      durationDays: 1,
      severity: 2,
      symptoms: const ['Fever'],
    );
    expect(caseId, 'case-2');
  });

  test('patient members accepts a valid empty canonical response', () async {
    adapter.respond(
      '/api/v1/families/me',
      status: 200,
      body: const {'members': <Object>[]},
    );

    final members = await DioPatientApi(
      client,
      devicePlatform: MobileDevicePlatform.android,
    ).getMembers();

    expect(members, isEmpty);
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/families/me',
    ]);
  });

  for (final status in [401, 403, 500]) {
    test('patient members propagates HTTP $status without fallback', () async {
      adapter.respond(
        '/api/v1/families/me',
        status: status,
        body: {'title': 'Synthetic HTTP $status'},
      );

      await expectLater(
        DioPatientApi(
          client,
          devicePlatform: MobileDevicePlatform.android,
        ).getMembers(),
        throwsA(isA<DioException>()),
      );
      expect(adapter.requests.map((request) => request.uri.path), [
        '/api/v1/families/me',
      ]);
    });
  }

  test('patient members rejects a missing members field', () async {
    adapter.respond(
      '/api/v1/families/me',
      status: 200,
      body: const <String, dynamic>{},
    );

    await expectLater(
      DioPatientApi(
        client,
        devicePlatform: MobileDevicePlatform.android,
      ).getMembers(),
      throwsA(isA<FormatException>()),
    );
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/families/me',
    ]);
  });

  test('patient members propagates connection failures', () async {
    adapter.fail(
      '/api/v1/families/me',
      Exception('Synthetic connection failure'),
    );

    await expectLater(
      DioPatientApi(
        client,
        devicePlatform: MobileDevicePlatform.android,
      ).getMembers(),
      throwsA(isA<DioException>()),
    );
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/families/me',
    ]);
  });

  test('appointments accepts a valid empty canonical response', () async {
    adapter.respond(
      '/api/v1/appointments/mine',
      status: 200,
      body: const <Object>[],
    );

    final appointments = await DioFamilyPortalApi(client).getMyAppointments();

    expect(appointments, isEmpty);
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/appointments/mine',
    ]);
  });

  for (final status in [401, 403, 500]) {
    test('appointments propagates HTTP $status without fallback', () async {
      adapter.respond(
        '/api/v1/appointments/mine',
        status: status,
        body: {'title': 'Synthetic HTTP $status'},
      );

      await expectLater(
        DioFamilyPortalApi(client).getMyAppointments(),
        throwsA(isA<DioException>()),
      );
      expect(adapter.requests.map((request) => request.uri.path), [
        '/api/v1/appointments/mine',
      ]);
    });
  }

  test('appointments rejects malformed canonical data', () async {
    adapter.respond(
      '/api/v1/appointments/mine',
      status: 200,
      body: const {'items': 'malformed'},
    );

    await expectLater(
      DioFamilyPortalApi(client).getMyAppointments(),
      throwsA(isA<FormatException>()),
    );
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/appointments/mine',
    ]);
  });

  test('appointments rejects a missing list envelope', () async {
    adapter.respond(
      '/api/v1/appointments/mine',
      status: 200,
      body: const <String, dynamic>{},
    );

    await expectLater(
      DioFamilyPortalApi(client).getMyAppointments(),
      throwsA(isA<FormatException>()),
    );
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/appointments/mine',
    ]);
  });

  test('appointments propagates connection failures', () async {
    adapter.fail(
      '/api/v1/appointments/mine',
      Exception('Synthetic connection failure'),
    );

    await expectLater(
      DioFamilyPortalApi(client).getMyAppointments(),
      throwsA(isA<DioException>()),
    );
    expect(adapter.requests.map((request) => request.uri.path), [
      '/api/v1/appointments/mine',
    ]);
  });

  test('patient API registers Android device tokens as ANDROID', () async {
    final api = DioPatientApi(
      client,
      devicePlatform: MobileDevicePlatform.android,
    );

    await api.subscribeDevice('synthetic-android-device-token');

    expect(adapter.lastRequest?.uri.path, '/api/v1/notifications/subscribe');
    expect(adapter.lastRequest?.data, {
      'deviceToken': 'synthetic-android-device-token',
      'platform': 'ANDROID',
    });
  });

  test('patient API registers iPhone device tokens as IOS', () async {
    final api = DioPatientApi(client, devicePlatform: MobileDevicePlatform.ios);

    await api.subscribeDevice('synthetic-ios-device-token');

    expect(adapter.lastRequest?.uri.path, '/api/v1/notifications/subscribe');
    expect(adapter.lastRequest?.data, {
      'deviceToken': 'synthetic-ios-device-token',
      'platform': 'IOS',
    });
  });

  test('401 expires session and clears tokens', () async {
    var expirationCount = 0;
    tokenStore.sessionExpirations.listen((_) => expirationCount++);

    await expectLater(
      client.dio.get<dynamic>('/unauthorized'),
      throwsA(isA<DioException>()),
    );
    await pumpEventQueue();

    expect(tokenStore.accessToken, isNull);
    expect(tokenStore.refreshToken, isNull);
    expect(expirationCount, 1);
  });
  for (final shared in [false, true]) {
    test(
      'report upload applies explicit sharing=$shared before extraction',
      () async {
        final directory = await Directory.systemTemp.createTemp(
          'fv-upload-test-',
        );
        addTearDown(() => directory.delete(recursive: true));
        final file = await File(
          '${directory.path}/synthetic.png',
        ).writeAsBytes([1, 2, 3]);
        adapter.respond(
          '/api/v1/members/member-1/lab-reports',
          status: 201,
          body: {'id': 'saved-report'},
        );
        adapter.respond(
          '/api/v1/lab-reports/saved-report/sharing',
          status: 200,
          body: {},
        );
        adapter.respond(
          '/api/v1/lab-reports/saved-report/extract',
          status: 200,
          body: {},
        );
        await DioMobileApi(client).uploadLabReport(
          memberId: 'member-1',
          path: file.path,
          sharedWithFamilyHead: shared,
        );
        final paths = adapter.requests.map((r) => r.uri.path).toList();
        expect(paths, [
          '/api/v1/members/member-1/lab-reports',
          if (shared) '/api/v1/lab-reports/saved-report/sharing',
          '/api/v1/lab-reports/saved-report/extract',
        ]);
        if (shared) {
          expect(adapter.requests[1].data, {'sharedWithFamilyHead': true});
        }
      },
    );
  }
  test(
    'saved report sharing failure is distinct and does not restart upload',
    () async {
      final directory = await Directory.systemTemp.createTemp(
        'fv-upload-test-',
      );
      addTearDown(() => directory.delete(recursive: true));
      final file = await File(
        '${directory.path}/synthetic.png',
      ).writeAsBytes([1, 2, 3]);
      adapter.respond(
        '/api/v1/members/member-1/lab-reports',
        status: 201,
        body: {'id': 'saved-report'},
      );
      adapter.respond(
        '/api/v1/lab-reports/saved-report/sharing',
        status: 403,
        body: {},
      );
      await expectLater(
        DioMobileApi(client).uploadLabReport(
          memberId: 'member-1',
          path: file.path,
          sharedWithFamilyHead: true,
        ),
        throwsA(
          isA<SavedReportUploadException>().having(
            (e) => e.message,
            'message',
            contains('saved privately'),
          ),
        ),
      );
      expect(adapter.requests.length, 2);
    },
  );
  test(
    'saved report extraction failure tells the user not to duplicate upload',
    () async {
      final directory = await Directory.systemTemp.createTemp(
        'fv-upload-test-',
      );
      addTearDown(() => directory.delete(recursive: true));
      final file = await File(
        '${directory.path}/synthetic.png',
      ).writeAsBytes([1, 2, 3]);
      adapter.respond(
        '/api/v1/members/member-1/lab-reports',
        status: 201,
        body: {'id': 'saved-report'},
      );
      adapter.respond(
        '/api/v1/lab-reports/saved-report/extract',
        status: 503,
        body: {},
      );
      await expectLater(
        DioMobileApi(
          client,
        ).uploadLabReport(memberId: 'member-1', path: file.path),
        throwsA(
          isA<SavedReportUploadException>().having(
            (e) => e.message,
            'message',
            contains('Do not upload it again'),
          ),
        ),
      );
      expect(adapter.requests.length, 2);
    },
  );
}
